  "components": [
    {
      "type": "claim",
      "quote": "La Sezione traduce in tedesco testi della Cancelleria federale e del presidente della Confederazione e controlla le traduzioni delle autorità federali redatte nei dipartimenti e negli uffici, contribuendo all'elevata qualità della comunicazione istituzionale plurilingue.",
      "gist": "The German Section translates texts from the Federal Chancellery and the President of the Confederation into German and checks translations by federal authorities in departments and offices, contributing to high-quality multilingual institutional communication."
    },
    {
      "type": "entity",
      "quote": "consiglio dell’ortografia tedesca («Rat für deutsche Rechtschreibung»)",
      "gist": "German Spelling Council (Rat für deutsche Rechtschreibung)"
    },
    {
      "type": "claim",
      "quote": "La Sezione tedesca collabora con organizzazioni nazionali e internazionali che si occupano di politica linguistica, ad esempio il consiglio dell’ortografia tedesca («Rat für deutsche Rechtschreibung»), in cui espone il punto di vista dell’Amministrazione federale e rappresenta gli interessi della Svizzera.",
      "gist": "The German Section collaborates with national and international organizations dealing with language policy, such as the German Spelling Council, where it presents the Federal Administration's viewpoint and represents Switzerland's interests."
    },
    {
      "type": "claim",
      "quote": "La Sezione tedesca mette a disposizione guide e altri ausili che agevolano e uniformano la redazione di atti ufficiali.",
      "gist": "The German Section provides guides and other tools that facilitate and standardize the drafting of official documents."
    }
  ]
}
